#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        return 1;
    }

    double *arr = (double *)malloc(n * sizeof(double));
    if (arr == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%lf", &arr[i]) != 1) {
            free(arr);
            return 1;
        }
    }

    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }
    double avg = sum / n;

    double max = arr[0];
    double min = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) max = arr[i];
        if (arr[i] < min) min = arr[i];
    }

    double variance = 0.0;
    for (int i = 0; i < n; i++) {
        double diff = arr[i] - avg;
        variance += diff * diff;
    }
    variance /= n;
    double std_dev = sqrt(variance);

    printf("Average: %.2f\n", avg);
    printf("Maximum: %.2f\n", max);
    printf("Minimum: %.2f\n", min);
    printf("Standard Deviation: %.2f\n", std_dev);

    free(arr);
    return 0;
}
